INSERT INTO platform.provision_details (id, provision_id, slug, title, status, seo_metadata, sections, published_at)
VALUES (gen_random_uuid(), (SELECT id FROM platform.provisions WHERE code = 'dich-vu' LIMIT 1), 'dich-vu', 'Hệ Sinh Thái Dịch Vụ Công Nghệ - SGO Việt Nam', 'PUBLISHED', '{"title":"Hệ Sinh Thái Dịch Vụ SGO Việt Nam | Giải Pháp Công Nghệ Toàn Diện","description":"Tối ưu quy trình vận hành, tự động hóa chăm sóc khách hàng và nâng tầm thương hiệu với bộ giải pháp công nghệ toàn diện từ SGODATA.","canonical":"https://sgodata.com/#dich-vu","keywords":["dịch vụ công nghệ","phần mềm quản trị","QR code","VR360","ERP","CRM","POS","Data BI"]}'::jsonb, '[{"id":"hero","sectionKey":"hero","componentType":"Hero","isActive":true,"content":{"legacyComponentType":"Header","legacyOrder":1,"props":{"badge":"Hệ sinh thái công nghệ","title":"Giải Pháp Toàn Diện Để <br /> Bứt Phá Doanh Số Kỷ Nguyên Số","description":"Tối ưu quy trình vận hành, tự động hóa chăm sóc khách hàng và nâng tầm thương hiệu với bộ công cụ chuyên nghiệp."}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"services-catalog","sectionKey":"services-catalog","componentType":"FeatureGrid","isActive":true,"content":{"legacyComponentType":"Services","legacyOrder":2,"props":{"sectionId":"dich-vu","initialVisibleCount":6,"serviceCatalogCode":"ALL_SERVICES"}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"partners","sectionKey":"partners","componentType":"FeatureGrid","isActive":true,"content":{"legacyComponentType":"Partners","legacyOrder":3,"props":{"badge":"Sự tin tưởng","title":"Đối Tác Đồng Hành Chiến Lược","description":"Hệ sinh thái công nghệ của SGO Việt Nam tự hào được đồng hành cùng các thương hiệu, tập đoàn và các hợp tác xã hàng đầu trên hành trình chuyển đổi số.","partners":[{"name":"TECH-CORP","icon":"fa-solid fa-layer-group"},{"name":"AGRI-FOOD","icon":"fa-solid fa-leaf"},{"name":"LOGISTICS","icon":"fa-solid fa-truck-fast"},{"name":"FINTECH","icon":"fa-solid fa-money-bill-transfer"},{"name":"RETAIL-MALL","icon":"fa-solid fa-store"},{"name":"EDU-SYSTEM","icon":"fa-solid fa-graduation-cap"}]}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"faq","sectionKey":"faq","componentType":"FAQ","isActive":true,"content":{"legacyComponentType":"FAQ","legacyOrder":4,"props":{"badge":"Hỗ trợ khách hàng","title":"Câu Hỏi Thường Gặp","description":"Tổng hợp những thắc mắc phổ biến của các chủ doanh nghiệp khi tìm hiểu và ứng dụng hệ sinh thái số của SGO Việt Nam."}},"style":{"theme":"light","spacing":"md","container":"normal"}}]'::jsonb, now())
