INSERT INTO platform.provision_details (id, provision_id, slug, title, status, seo_metadata, sections, published_at)
VALUES (gen_random_uuid(), (SELECT id FROM platform.provisions WHERE code = 'qr' LIMIT 1), 'qr-code', 'Tạo Mã QR Miễn Phí - Sạch 100% Không Quảng Cáo | SGO VIỆT NAM', 'PUBLISHED', '{"title":"Tạo Mã QR Miễn Phí - Sạch 100% Không Quảng Cáo | SGO VIỆT NAM","description":"QR Code sạch 100%, không bị chèn quảng cáo trung gian, không giới hạn lượt quét.","canonical":"https://sgodata.com/qr-code.html","keywords":["tạo mã qr miễn phí","làm qr code online","qr code không quảng cáo","sgodata"]}'::jsonb, '[{"id":"qr-header","sectionKey":"qr-header","componentType":"Hero","isActive":true,"content":{"legacyComponentType":"QrHeader","legacyOrder":1,"props":{"badge":"Miễn phí 100% - Không giới hạn lượt quét","title":"Sở Hữu Mã QR Code Sạch <br /><span class=\"text-blue-600\">Nói Không Với Quảng Cáo Chèn Ngầm</span>","description":"Bạn in mã QR lên danh thiếp, bao bì sản phẩm hay menu nhà hàng nhưng khách quét lại ra quảng cáo game bài, shopee, Lazada? SGO đem lại giải pháp QR dẫn thẳng tới đích!","ctaPrimary":{"text":"Bắt đầu tạo ngay","link":"#tao-form"},"ctaSecondary":{"text":"Tìm hiểu thêm","link":"#uu-diem"}}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"qr-warning","sectionKey":"qr-warning","componentType":"ImageText","isActive":true,"content":{"legacyComponentType":"QrWarning","legacyOrder":2,"props":{"warningTitle":"Cảnh giác với các website tạo QR miễn phí chứa quảng cáo","warningDesc":"Nhiều dịch vụ cho tạo mã QR miễn phí nhưng sau vài ngày sẽ tự động chuyển hướng khách quét sang trang quảng cáo cá cược hoặc bán hàng trung gian, gây mất uy tín thương hiệu nghiêm trọng."}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"qr-features","sectionKey":"qr-features","componentType":"FeatureGrid","isActive":true,"content":{"legacyComponentType":"QrFeatures","legacyOrder":3,"props":{"sectionBadge":"Giá trị cốt lõi","sectionTitle":"Mã QR Được Khởi Tạo Tại SGO Có Gì Khác Biệt?","items":[{"icon":"fa-solid fa-eye-slash","title":"Sạch 100%","desc":"Tuyệt đối không chèn pop-up, không điều hướng quảng cáo bẩn gây ức chế cho khách hàng."},{"icon":"fa-solid fa-infinity","title":"Vô hạn lượt quét","desc":"Mã QR hoạt động vĩnh viễn, không giới hạn dung lượng truy cập, yên tâm in ấn số lượng lớn."},{"icon":"fa-solid fa-bolt","title":"Tốc độ tức thì","desc":"Định dạng mã tối ưu mật độ điểm ảnh, giúp camera điện thoại nhận diện nhanh dưới 0.5 giây."},{"icon":"fa-solid fa-headset","title":"Hỗ trợ kỹ thuật","desc":"Được đội ngũ kỹ sư hạ tầng của SGO hỗ trợ giám sát, đảm bảo đường truyền luôn thông suốt."}]}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"qr-comparison","sectionKey":"qr-comparison","componentType":"ImageText","isActive":true,"content":{"legacyComponentType":"QrComparison","legacyOrder":4,"props":{"title":"Xem xét & Cân nhắc trước khi quyết định in ấn","rows":[{"feature":"Quảng cáo hiển thị kèm theo","sgo":"Hoàn toàn KHÔNG","others":"Có (Sau vài ngày sử dụng)"},{"feature":"Giới hạn thời hạn hoạt động","sgo":"Vĩnh viễn trọn đời","others":"Giới hạn 14 - 30 ngày"},{"feature":"Tốc độ phản hồi chuyển link","sgo":"Trực tiếp (Dưới 0.5s)","others":"Chậm (Chờ tải trang đệm)"},{"feature":"Chi phí duy trì hệ thống","sgo":"0đ (Tài trợ miễn phí)","others":"Đòi phí bản quyền gia hạn"}]}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"qr-form","sectionKey":"qr-form","componentType":"CTA","isActive":true,"content":{"legacyComponentType":"QrForm","legacyOrder":5,"props":{"formTitle":"Đăng ký nhận mã QR Code Miễn Phí","formSubtitle":"Điền thông tin đích cần chuyển hướng và nhận ngay file vector chất lượng cao"}},"style":{"theme":"light","spacing":"md","container":"normal"}}]'::jsonb, now())
