INSERT INTO platform.provision_details (id, provision_id, slug, title, status, seo_metadata, sections, published_at)
VALUES (gen_random_uuid(), (SELECT id FROM platform.provisions WHERE code = 'truy-xuat' LIMIT 1), 'truy-xuat-nguon-goc', 'Giải Pháp Truy Xuất Nguồn Gốc Sản Phẩm Toàn Diện - SGO Việt Nam', 'PUBLISHED', '{"title":"Giải Pháp Truy Xuất Nguồn Gốc Sản Phẩm Toàn Diện - SGO Việt Nam","description":"Số hóa nhật ký sản xuất, minh bạch chuỗi cung ứng bằng QR Code độc bản, chống hàng giả và hỗ trợ doanh nghiệp đáp ứng tiêu chuẩn xuất khẩu.","canonical":"https://sgodata.com/truy-xuat-nguon-goc.html","keywords":["truy xuất nguồn gốc","phần mềm truy xuất","qr code chống hàng giả","SGO Trace"]}'::jsonb, '[{"id":"trace-header","sectionKey":"trace-header","componentType":"Hero","isActive":true,"content":{"legacyComponentType":"TraceHeader","legacyOrder":1,"props":{"title":"Giải Pháp Truy Xuất Nguồn Gốc <br /> Minh Bạch Chuỗi Cung Ứng Toàn Diện","description":"Số hóa quy trình từ vùng trồng, nhà máy đến tay người tiêu dùng. Bảo vệ thương hiệu vững chắc bằng hệ thống mã QR Code định danh độc bản.","ctaPrimary":{"text":"Đăng ký tư vấn ngay","link":"#dang-ky"},"ctaSecondary":{"text":"Tìm hiểu tính năng","link":"#tinh-nang"}}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"trace-why","sectionKey":"trace-why","componentType":"FeatureGrid","isActive":true,"content":{"legacyComponentType":"TraceWhy","legacyOrder":2,"props":{"title":"Tại Sao Doanh Nghiệp Cần Truy Xuất Nguồn Gốc?","points":["Bảo vệ uy tín thương hiệu trước nạn hàng giả, hàng nhái tràn lan.","Đáp ứng đầy đủ các tiêu chuẩn khắt khe để xuất khẩu và vào chuỗi siêu thị lớn.","Gia tăng niềm tin tuyệt đối từ người tiêu dùng khi quét mã rõ ràng nhật ký."]}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"trace-features","sectionKey":"trace-features","componentType":"FeatureGrid","isActive":true,"content":{"legacyComponentType":"TraceFeatures","legacyOrder":3,"props":{"title":"Tính Năng Nổi Bật Của Hệ Thống SGO Trace","features":[{"icon":"fa-solid fa-qrcode","title":"Mã QR Code Định Danh Độc Bản","desc":"Cấp mã QR biến đổi hoặc mã QR theo lô duy nhất. Hiển thị chứng nhận VietGAP, GlobalGAP, OCOP."},{"icon":"fa-solid fa-pen-to-square","title":"Nhật Ký Sản Xuất Điện Tử","desc":"Ghi chép thời gian thực quá trình bón phân, phun thuốc, thu hoạch ngay trên điện thoại. Chống tẩy xóa."},{"icon":"fa-solid fa-boxes-packing","title":"Quản Lý Lô Hàng & Chuỗi Cung Ứng","desc":"Giám sát chặt chẽ hành trình từ thu mua, sơ chế, logistics đến hệ thống siêu thị, điểm bán lẻ."},{"icon":"fa-solid fa-shield-halved","title":"Tích Hợp Chống Hàng Giả","desc":"Cảnh báo tức thì khi mã QR bị sao chép hoặc quét bất thường tại nhiều vị trí địa lý cùng lúc."},{"icon":"fa-solid fa-chart-line","title":"Báo Cáo & Thống Kê Quét","desc":"Dashboard thống kê chi tiết số lượt quét mã, khu vực địa lý, thấu hiểu hành vi khách hàng."},{"icon":"fa-solid fa-link","title":"May Đo & Tích Hợp Hệ Thống","desc":"Kết nối API mượt mà với hệ thống quản trị CRM / ERP hiện tại của doanh nghiệp."}]}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"trace-benefits","sectionKey":"trace-benefits","componentType":"FeatureGrid","isActive":true,"content":{"legacyComponentType":"TraceBenefits","legacyOrder":4,"props":{"title":"Lợi Ích Thực Tiễn Cho Doanh Nghiệp Nông Sản & Sản Xuất"}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"trace-form","sectionKey":"trace-form","componentType":"CTA","isActive":true,"content":{"legacyComponentType":"TraceForm","legacyOrder":5,"props":{"formTitle":"Đăng ký Khảo Sát & Tư Vấn Hệ Thống Truy Xuất Nguồn Gốc"}},"style":{"theme":"light","spacing":"md","container":"normal"}}]'::jsonb, now())
