INSERT INTO platform.provision_details (id, provision_id, slug, title, status, seo_metadata, sections, published_at)
VALUES (gen_random_uuid(), (SELECT id FROM platform.provisions WHERE code = 'vr360' LIMIT 1), 'vr360', 'Giải Pháp VR360 Du Lịch & Lưu Trú - Nâng Tầm Trải Nghiệm Khách Hàng', 'PUBLISHED', '{"title":"Giải Pháp VR360 Du Lịch & Lưu Trú - SGO Việt Nam","description":"Số hóa không gian 360 độ trực quan, sa bàn ảo cho resort, khách sạn, tăng tỷ lệ đặt phòng.","canonical":"https://sgodata.com/vr360.html","keywords":["VR360 du lịch","sa bàn ảo resort","thực tế ảo khách sạn","tour 360 lưu trú"]}'::jsonb, '[{"id":"vr-header","sectionKey":"vr-header","componentType":"Hero","isActive":true,"content":{"legacyComponentType":"VrHeader","legacyOrder":1,"props":{"title":"Công Nghệ Tour Thực Tế Ảo VR360 <br /> Đột Phá Doanh Thu Du Lịch & Lưu Trú","description":"Mang không gian nghỉ dưỡng sống động đến ngay màn hình của du khách. Trải nghiệm trực quan trước khi quyết định đặt phòng."}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"vr-benefits","sectionKey":"vr-benefits","componentType":"FeatureGrid","isActive":true,"content":{"legacyComponentType":"VrBenefits","legacyOrder":2,"props":{"title":"Bứt Phá Tỷ Lệ Đặt Phòng Nhờ Trải Nghiệm Thực Tế Ảo 3D"}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"vr-features","sectionKey":"vr-features","componentType":"FeatureGrid","isActive":true,"content":{"legacyComponentType":"VrFeatures","legacyOrder":3,"props":{"title":"Các Tính Năng Cao Cấp Tích Hợp Trong Tour VR360"}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"vr-pricing","sectionKey":"vr-pricing","componentType":"Pricing","isActive":true,"content":{"legacyComponentType":"VrPricing","legacyOrder":4,"props":{"sectionTitle":"Báo Giá Dịch Vụ Tour Thực Tế Ảo VR360","specialOffer":"ĐẶC QUYỀN TRỌN ĐỜI: THU PHÍ 01 LẦN DỰNG – MIỄN PHÍ DUY TRÌ TRỌN ĐỜI. TẶNG MIỄN PHÍ 01 WEBSITE RIÊNG","demoLink":"https://vr.sgodata.com/demo-resort","plansCatalog":"VR360_PLANS"}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"vr-faq","sectionKey":"vr-faq","componentType":"FAQ","isActive":true,"content":{"legacyComponentType":"VrFaq","legacyOrder":5,"props":{"title":"Giải Đáp Thắc Mắc Về Dịch Vụ VR360"}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"vr-form","sectionKey":"vr-form","componentType":"CTA","isActive":true,"content":{"legacyComponentType":"VrForm","legacyOrder":6,"props":{"title":"Đăng Ký Tư Vấn & Khảo Sát Không Gian VR360"}},"style":{"theme":"light","spacing":"md","container":"normal"}}]'::jsonb, now())
