INSERT INTO platform.provision_details (id, provision_id, slug, title, status, seo_metadata, sections, published_at)
VALUES (gen_random_uuid(), (SELECT id FROM platform.provisions WHERE code = 'pos' LIMIT 1), 'pos', 'Phần Mềm Quản Lý Bán Hàng SGO POS - Đơn Giản, Tốc Độ, Hiệu Quả', 'PUBLISHED', '{"title":"Phần Mềm Quản Lý Bán Hàng SGO POS","description":"Tính tiền 3s, quản lý kho thông minh, báo cáo doanh thu realtime, hỗ trợ đa ngành hàng.","canonical":"https://sgodata.com/pos.html","keywords":["phần mềm bán hàng","sgo pos","tính tiền siêu tốc","quản lý kho"]}'::jsonb, '[{"id":"pos-header","sectionKey":"pos-header","componentType":"Hero","isActive":true,"content":{"legacyComponentType":"PosHeader","legacyOrder":1,"props":{"title":"Phần Mềm Quản Lý Bán Hàng SGO POS <br /> Đơn Giản - Chuẩn Xác - Tốc Độ","description":"Tối ưu quy trình thu ngân, kiểm soát kho hàng chặt chẽ và theo dõi doanh thu theo thời gian thực mọi lúc mọi nơi."}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"pos-features","sectionKey":"pos-features","componentType":"FeatureGrid","isActive":true,"content":{"legacyComponentType":"PosFeatures","legacyOrder":2,"props":{"title":"Tính Năng Vượt Trội Của SGO POS","items":[{"title":"Tính tiền siêu tốc 3 giây","desc":"Giao diện cảm ứng trực quan, quét mã vạch nhanh, in hóa đơn tức thì."},{"title":"Quản lý tồn kho thông minh","desc":"Cảnh báo hàng sắp hết, tự động trừ kho khi bán hàng, kiểm kho chống thất thoát."},{"title":"Báo cáo doanh thu thời gian thực","desc":"Theo dõi lợi nhuận, dòng tiền, hàng bán chạy ngay trên app điện thoại."},{"title":"Đồng bộ đa kênh & Sàn TMĐT","desc":"Kết nối đơn hàng Shopee, TikTok Shop, Lazada và bán tại cửa hàng tập trung."}]}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"pos-industries","sectionKey":"pos-industries","componentType":"FeatureGrid","isActive":true,"content":{"legacyComponentType":"PosIndustries","legacyOrder":3,"props":{"title":"Giải Pháp Chuyên Sâu Cho Từng Ngành Hàng","industries":["Tạp hóa & Siêu thị mini","Thời trang & Mỹ phẩm","Nhà hàng & F&B","Chuỗi cửa hàng bán lẻ"]}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"pos-form","sectionKey":"pos-form","componentType":"CTA","isActive":true,"content":{"legacyComponentType":"PosForm","legacyOrder":4,"props":{"title":"Đăng Ký Dùng Thử Miễn Phí 07 Ngày Đầy Đủ Tính Năng"}},"style":{"theme":"light","spacing":"md","container":"normal"}}]'::jsonb, now())
