INSERT INTO platform.provision_details (id, provision_id, slug, title, status, seo_metadata, sections, published_at)
VALUES (gen_random_uuid(), (SELECT id FROM platform.provisions WHERE code = 'zns' LIMIT 1), 'zns', 'Giải Pháp Tin Nhắn Zalo ZNS & Chăm Sóc Khách Hàng OA - SGO Việt Nam', 'PUBLISHED', '{"title":"Giải Pháp Tin Nhắn Zalo ZNS & Chăm Sóc Khách Hàng OA - SGO Việt Nam","description":"Gửi tin nhắn Zalo tự động qua Brandname, tối ưu 60% chi phí so với SMS truyền thống.","canonical":"https://sgodata.com/zns.html","keywords":["zalo zns","tin nhắn cskh","zalo oa","brandname zalo"]}'::jsonb, '[{"id":"zns-header","sectionKey":"zns-header","componentType":"Hero","isActive":true,"content":{"legacyComponentType":"ZnsHeader","legacyOrder":1,"props":{"title":"Giải Pháp Gửi Tin Nhắn Tự Động Zalo ZNS <br /> Nâng Tầm Trải Nghiệm Khách Hàng","description":"Chăm sóc khách hàng chủ động thông qua số điện thoại với chi phí tiết kiệm hơn SMS truyền thống, tỷ lệ mở tin vượt trội trên 90%."}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"zns-why","sectionKey":"zns-why","componentType":"FeatureGrid","isActive":true,"content":{"legacyComponentType":"ZnsWhy","legacyOrder":2,"props":{"title":"Tại Sao Nên Chuyển Đổi Từ SMS Sang Zalo ZNS?","reasons":["Chi phí chỉ bằng 30-50% so với tin nhắn SMS Brandname thông thường.","Hiển thị Logo, tên thương hiệu tích vàng uy tín, tạo thiện cảm lớn cho khách hàng.","Nội dung chứa nút bấm tương tác (Call to Action), dẫn thẳng về Website hoặc đơn hàng."]}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"zns-use-cases","sectionKey":"zns-use-cases","componentType":"ImageText","isActive":true,"content":{"legacyComponentType":"ZnsUseCases","legacyOrder":3,"props":{"title":"Các Kịch Bản Ứng Dụng ZNS Phổ Biến","scenarios":["Xác nhận đơn hàng và cập nhật hành trình vận chuyển","Gửi thông báo biến động số dư, điểm tích lũy thành viên","Chúc mừng sinh nhật tặng kèm mã giảm giá đặc quyền","Nhắc lịch hẹn dịch vụ, bảo dưỡng hoặc gia hạn hợp đồng"]}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"zns-form","sectionKey":"zns-form","componentType":"CTA","isActive":true,"content":{"legacyComponentType":"ZnsForm","legacyOrder":4,"props":{"title":"Nhận Báo Giá Gói Tin Nhắn Zalo ZNS Cho Doanh Nghiệp"}},"style":{"theme":"light","spacing":"md","container":"normal"}}]'::jsonb, now())
