INSERT INTO platform.provision_details (id, provision_id, slug, title, status, seo_metadata, sections, published_at)
VALUES (gen_random_uuid(), (SELECT id FROM platform.provisions WHERE code = 'web' LIMIT 1), 'web', 'Thiết Kế Website Chuyên Nghiệp Chuẩn SEO - SGO Web', 'PUBLISHED', '{"title":"Thiết Kế Website Chuyên Nghiệp Chuẩn SEO - SGO Web","description":"Website chuẩn SEO, tặng tên miền và hosting, bảo hành trọn đời, bàn giao 100% mã nguồn.","canonical":"https://sgodata.com/web.html","keywords":["thiết kế website","làm web chuẩn seo","thiết kế web theo yêu cầu","sgo web"]}'::jsonb, '[{"id":"web-header","sectionKey":"web-header","componentType":"Hero","isActive":true,"content":{"legacyComponentType":"WebHeader","legacyOrder":1,"props":{"title":"Thiết Kế Website Chuyên Nghiệp <br /> Độc Quyền Nhận Diện & Tối Ưu Tỷ Lệ Chuyển Đổi","description":"Website chuẩn cấu trúc SEO Google, giao diện mượt mà trên di động, tốc độ tải trang thần tốc."}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"web-pricing","sectionKey":"web-pricing","componentType":"Pricing","isActive":true,"content":{"legacyComponentType":"WebPricing","legacyOrder":2,"props":{"title":"Bảng Giá Dịch Vụ Thiết Kế Web Minh Bạch","plansCatalog":"WEB_PLANS"}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"web-workflow","sectionKey":"web-workflow","componentType":"FeatureGrid","isActive":true,"content":{"legacyComponentType":"WebWorkflow","legacyOrder":3,"props":{"title":"Quy Trình Triển Khai Website Chuẩn 4 Bước Tại SGO","steps":[{"step":"01","name":"Khảo sát & Tư vấn giải pháp","desc":"Tiếp nhận yêu cầu, định hình cấu trúc sitemap và phân tích đối thủ."},{"step":"02","name":"Thiết kế giao diện UI/UX","desc":"Phác thảo layout độc quyền phù hợp bộ nhận diện thương hiệu."},{"step":"03","name":"Lập trình & Tối ưu SEO","desc":"Xây dựng tính năng, tối ưu mã nguồn và kiểm tra tốc độ PageSpeed."},{"step":"04","name":"Nghiệm thu & Bàn giao","desc":"Bàn giao 100% source code, hướng dẫn quản trị và kích hoạt bảo hành trọn đời."}]}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"web-faq","sectionKey":"web-faq","componentType":"FAQ","isActive":true,"content":{"legacyComponentType":"WebFaq","legacyOrder":4,"props":{"title":"Câu Hỏi Thường Gặp Khi Thiết Kế Website"}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"web-form","sectionKey":"web-form","componentType":"CTA","isActive":true,"content":{"legacyComponentType":"WebForm","legacyOrder":5,"props":{"title":"Đăng Ký Tư Vấn Ý Tưởng Thiết Kế Website"}},"style":{"theme":"light","spacing":"md","container":"normal"}}]'::jsonb, now())
