INSERT INTO platform.provision_details (id, provision_id, slug, title, status, seo_metadata, sections, published_at)
VALUES (gen_random_uuid(), (SELECT id FROM platform.provisions WHERE code = 'erp' LIMIT 1), 'erp', 'Giải Pháp Quản Trị Doanh Nghiệp Toàn Diện ERP - SGO Việt Nam', 'PUBLISHED', '{"title":"Giải Pháp Quản Trị Doanh Nghiệp Toàn Diện ERP - SGO Việt Nam","description":"Số hóa quản trị khách hàng, nhân sự, tài chính, sản xuất, báo cáo BI điều hành thông minh.","canonical":"https://sgodata.com/erp.html","keywords":["phần mềm erp","quản trị doanh nghiệp","sgo erp","crm erp may đo"]}'::jsonb, '[{"id":"erp-header","sectionKey":"erp-header","componentType":"Hero","isActive":true,"content":{"legacyComponentType":"ErpHeader","legacyOrder":1,"props":{"title":"Hệ Thống Quản Trị Doanh Nghiệp SGO ERP <br /> Hợp Nhất & Tự Động Hóa Mọi Luồng Vận Hành","description":"Loại bỏ silo dữ liệu rời rạc, chuẩn hóa quy trình làm việc giữa các phòng ban với nền tảng may đo linh hoạt."}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"erp-modules","sectionKey":"erp-modules","componentType":"FeatureGrid","isActive":true,"content":{"legacyComponentType":"ErpModules","legacyOrder":2,"props":{"title":"Phân Hệ Cốt Lõi Được \"May Đo\" Chuyên Biệt","modules":[{"title":"Quản Trị Tài Chính - Kế Toán","icon":"fa-solid fa-scale-balanced","desc":"Tự động hóa dòng tiền, hạch toán công nợ phải thu/phải trả, báo cáo realtime."},{"title":"Quản Lý Chuỗi Cung Ứng & Kho","icon":"fa-solid fa-boxes-stacked","desc":"Kiểm soát vị trí kho, hạn mức tồn kho tối ưu, quy trình quét mã barcode/QR."},{"title":"Quản Trị Nhân Sự & Tiền Lương","icon":"fa-solid fa-users-gear","desc":"Số hóa hồ sơ nhân sự, tự động hóa chấm công, tính lương KPI minh bạch."},{"title":"Quản Trị Khách Hàng CRM & Bán Hàng","icon":"fa-solid fa-handshake-angle","desc":"Chuẩn hóa phễu bán hàng từ Leads đến Hợp đồng, theo dõi lịch sử chăm sóc."},{"title":"Quản Lý Sản Xuất (MRP, BOM)","icon":"fa-solid fa-industry","desc":"Hoạch định nguyên vật liệu, lập lịch trình sản xuất và tính giá thành sản phẩm."},{"title":"Hệ Thống Báo Cáo Thông Minh BI","icon":"fa-solid fa-chart-line","desc":"Trực quan hóa chỉ số kinh doanh dưới dạng biểu đồ động, dự báo xu hướng."}]}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"erp-why","sectionKey":"erp-why","componentType":"FeatureGrid","isActive":true,"content":{"legacyComponentType":"ErpWhy","legacyOrder":3,"props":{"title":"Tại Sao Nên Chọn May Đo ERP Tại SGO Việt Nam?","highlights":["Bảo mật chuẩn ISO","Không bị gò bó bởi tính năng thừa","Dễ dàng nâng cấp theo tốc độ mở rộng công ty"]}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"erp-form","sectionKey":"erp-form","componentType":"CTA","isActive":true,"content":{"legacyComponentType":"ErpForm","legacyOrder":4,"props":{"title":"Yêu Cầu Demo Trực Tiếp Hệ Thống SGO ERP"}},"style":{"theme":"light","spacing":"md","container":"normal"}}]'::jsonb, now())
