INSERT INTO platform.provision_details (id, provision_id, slug, title, status, seo_metadata, sections, published_at)
VALUES (gen_random_uuid(), (SELECT id FROM platform.provisions WHERE code = 'data-bi' LIMIT 1), 'data-bi', 'Hạ Tầng Dữ Liệu & Business Intelligence (BI) - SGO Data', 'PUBLISHED', '{"title":"Hạ Tầng Dữ Liệu & BI Chuyên Sâu - SGO Data","description":"Biến dữ liệu thô thành quyết định chiến lược. Trực quan hóa báo cáo điều hành thời gian thực.","canonical":"https://sgodata.com/data-bi.html","keywords":["hạ tầng dữ liệu","data warehouse","power bi","looker studio","data lake"]}'::jsonb, '[{"id":"bi-header","sectionKey":"bi-header","componentType":"Hero","isActive":true,"content":{"legacyComponentType":"DataBiHeader","legacyOrder":1,"props":{"title":"Hạ Tầng Dữ Liệu & Business Intelligence (BI) <br /> Biến Dữ Liệu Thô Thành Quyết Định Chiến Lược","description":"Tập hợp, làm sạch và trực quan hóa toàn bộ dòng chảy dữ liệu kinh doanh của doanh nghiệp lên dashboard điều hành thời gian thực."}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"bi-stats","sectionKey":"bi-stats","componentType":"FeatureGrid","isActive":true,"content":{"legacyComponentType":"DataBiStats","legacyOrder":2,"props":{"stats":[{"number":"70%","label":"Thời gian lập báo cáo được tinh gọn"},{"number":"100%","label":"Dữ liệu được cập nhật tự động realtime"},{"number":"03+","label":"Nền tảng BI được hỗ trợ: Power BI, Looker, Tableau"}]}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"bi-solutions","sectionKey":"bi-solutions","componentType":"FeatureGrid","isActive":true,"content":{"legacyComponentType":"DataBiSolutions","legacyOrder":3,"props":{"title":"Giải Pháp Dữ Liệu Toàn Diện Từ SGO Data","solutions":[{"title":"Data Warehouse & Data Lake","desc":"Lưu trữ tập trung mọi nguồn dữ liệu kế toán, CRM, bán hàng, website."},{"title":"Tự động hóa luồng ETL/ELT","desc":"Trích xuất, chuyển đổi và nạp dữ liệu hoàn toàn tự động không cần nhân sự gõ Excel."},{"title":"Dashboard Điều Hành Thông Minh","desc":"Báo cáo doanh thu, chi phí, hiệu suất nhân sự trên di động cho Ban Lãnh đạo."}]}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"bi-faq","sectionKey":"bi-faq","componentType":"FAQ","isActive":true,"content":{"legacyComponentType":"DataBiFaq","legacyOrder":4,"props":{"title":"Câu Hỏi Thường Gặp Về Dịch Vụ Data & BI"}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"bi-form","sectionKey":"bi-form","componentType":"CTA","isActive":true,"content":{"legacyComponentType":"DataBiForm","legacyOrder":5,"props":{"title":"Đăng Ký Tư Vấn Khảo Sát Kiến Trúc Dữ Liệu"}},"style":{"theme":"light","spacing":"md","container":"normal"}}]'::jsonb, now())
