INSERT INTO platform.provision_details (id, provision_id, slug, title, status, seo_metadata, sections, published_at)
VALUES (gen_random_uuid(), (SELECT id FROM platform.provisions WHERE code = 'cloud' LIMIT 1), 'ha-tang', 'Hạ Tầng, Lưu Trữ Cloud & Email Doanh Nghiệp Toàn Diện - SGO Việt Nam', 'PUBLISHED', '{"title":"Hạ Tầng, Lưu Trữ Cloud & Email Doanh Nghiệp - SGO Việt Nam","description":"Tên miền, Cloud Server, Hosting tốc độ cao, Email doanh nghiệp bảo mật, Uptime 99.99%.","canonical":"https://sgodata.com/cloud-server.html","keywords":["tên miền","hosting","cloud server","email doanh nghiệp","vps việt nam"]}'::jsonb, '[{"id":"infra-header","sectionKey":"infra-header","componentType":"Hero","isActive":true,"content":{"legacyComponentType":"InfraHeader","legacyOrder":1,"props":{"title":"Hạ Tầng & Lưu Trữ Cloud Doanh Nghiệp <br /> Tốc Độ Cao, Ổn Định Uptime 99.99%","description":"Nền tảng máy chủ vận hành mạnh mẽ cho website, hệ thống ERP và email doanh nghiệp với tiêu chuẩn an toàn quốc tế."}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"infra-services","sectionKey":"infra-services","componentType":"ImageText","isActive":true,"content":{"legacyComponentType":"InfraServices","legacyOrder":2,"props":{"title":"Các Nhóm Dịch Vụ Hạ Tầng Nổi Bật","services":[{"name":"Đăng Ký Tên Miền","desc":"Cung cấp tên miền quốc gia .vn, .com.vn và tên miền quốc tế với thủ tục kích hoạt nhanh gọn."},{"name":"Hosting Tốc Độ Cao","desc":"Trang bị ổ cứng NVMe SSD, bảng điều khiển cPanel, tăng tốc website gấp 5 lần."},{"name":"Cloud Server / VPS","desc":"Nâng cấp linh hoạt CPU/RAM không gián đoạn, sao lưu định kỳ hàng tuần."},{"name":"Email Doanh Nghiệp","desc":"Hệ thống email theo tên miền công ty, bảo mật chống spam, vào inbox 99%."}]}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"infra-advantages","sectionKey":"infra-advantages","componentType":"FeatureGrid","isActive":true,"content":{"legacyComponentType":"InfraAdvantages","legacyOrder":3,"props":{"title":"Cam Kết Chất Lượng Dịch Vụ Từ SGO"}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"infra-faq","sectionKey":"infra-faq","componentType":"FAQ","isActive":true,"content":{"legacyComponentType":"InfraFaq","legacyOrder":4,"props":{"title":"Câu Hỏi Thường Gặp Về Hạ Tầng & Cloud Server"}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"infra-form","sectionKey":"infra-form","componentType":"CTA","isActive":true,"content":{"legacyComponentType":"InfraForm","legacyOrder":5,"props":{"title":"Đăng Ký Khảo Sát Nhu Cầu Hạ Tầng Cloud"}},"style":{"theme":"light","spacing":"md","container":"normal"}}]'::jsonb, now())
