VALUES (gen_random_uuid(), (SELECT id FROM platform.provisions WHERE code = 'ban-quyen' LIMIT 1), 'ban-quyen', 'Sgodata.com - Bản Quyền Phần Mềm Chính Hãng Giá Tốt Nhất', 'PUBLISHED', '{"title":"Sgodata.com - Bản Quyền Phần Mềm Chính Hãng Giá Tốt Nhất","description":"Bản Quyền Windows, Office & Server Giá Tốt Nhất Cho Doanh Nghiệp & Cá Nhân.","canonical":"https://sgodata.com/ban-quyen.html","keywords":["bản quyền windows","key office 2021","office 365","windows server key"]}'::jsonb, '[{"id":"license-header","sectionKey":"license-header","componentType":"Hero","isActive":true,"content":{"legacyComponentType":"LicenseHeader","legacyOrder":1,"props":{"title":"Bản Quyền Phần Mềm Chính Hãng <br /> An Toàn Bảo Mật, Kích Hoạt Trực Tiếp Từ Microsoft","description":"Giải pháp phần mềm có bản quyền giá tốt nhất cho doanh nghiệp và người dùng cá nhân. Bảo hành trọn đời máy."}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"license-products","sectionKey":"license-products","componentType":"Pricing","isActive":true,"content":{"legacyComponentType":"LicenseProducts","legacyOrder":2,"props":{"title":"Danh Mục Sản Phẩm Bản Quyền Phổ Biến","plansCatalog":"LICENSE_PLANS"}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"license-features","sectionKey":"license-features","componentType":"FeatureGrid","isActive":true,"content":{"legacyComponentType":"LicenseFeatures","legacyOrder":3,"props":{"title":"Tại Sao Nên Mua Bản Quyền Tại SGODATA?","features":[{"title":"Chính hãng 100%","desc":"Kích hoạt trực tuyến qua máy chủ Microsoft, nhận bản cập nhật bảo mật liên tục."},{"title":"Bảo hành trọn đời máy","desc":"Hỗ trợ 1 đổi 1 nhanh chóng nếu key phát sinh lỗi trong quá trình sử dụng."},{"title":"Giao key thần tốc","desc":"Nhận key bản quyền và hướng dẫn kích hoạt tự động qua Zalo/Email trong 3-5 phút."}]}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"license-steps","sectionKey":"license-steps","componentType":"ImageText","isActive":true,"content":{"legacyComponentType":"LicenseSteps","legacyOrder":4,"props":{"title":"Quy Trình Mua & Kích Hoạt Key 4 Bước Đơn Giản"}},"style":{"theme":"light","spacing":"md","container":"normal"}},{"id":"license-faq","sectionKey":"license-faq","componentType":"FAQ","isActive":true,"content":{"legacyComponentType":"LicenseFaq","legacyOrder":5,"props":{"title":"Câu Hỏi Thường Gặp Về Key Bản Quyền"}},"style":{"theme":"light","spacing":"md","container":"normal"}}]'::jsonb, now())
